)

func main() {
	nums := []int{4, 9, 16, 25}
	results := make(chan int, len(nums))
	var wg sync.WaitGroup
	for _, n := range nums {
		wg.Go(func() { // Go 1.25: Add(1) + go + Done() bitta chaqiruvda
			results <- n * 10
		})
	}
	wg.Wait()
	close(results)

	var out []int
	for r := range results {
		out = append(out, r)
	}
	slices.Sort(out)
	fmt.Println(out)
}

