func Add(a, b int) int { return a + b }

// Clamp limits v to the range [lo, hi].
func Clamp(v, lo, hi int) int {
	return min(max(v, lo), hi)
}

func main() {
	fmt.Println(Add(2, 3), Clamp(15, 0, 10), Clamp(-4, 0, 10))
}

