// Perimeter returns the perimeter of a w×h rectangle.
//
// Deprecated: use Border instead, which also accepts a stroke width.
func Perimeter(w, h float64) float64 { return 2 * (w + h) }

// Border returns the border length of a w×h rectangle with the given stroke.
func Border(w, h, stroke float64) float64 { return 2*(w+h) + 4*stroke }

func main() {
	fmt.Println(Perimeter(3, 4)) // staticcheck SA1019: Perimeter is deprecated
	fmt.Println(Border(3, 4, 0.5))
}

