import (
	"fmt"
	"strings"
	"unicode"
)

// Normalize cleans a user-entered name.
//
// # Rules
//
// The following transformations are applied in order:
//   - leading and trailing spaces are removed
//   - the first letter is upper-cased
//
// Example:
//
//	Normalize("  aziz ") // "Aziz"
//
// See also [strings.TrimSpace].
func Normalize(s string) string {
	s = strings.TrimSpace(s)
	if s == "" {
		return s
	}
	r := []rune(s)
	r[0] = unicode.ToUpper(r[0])
	return string(r)
}

func main() {
	fmt.Println(Normalize("  aziz "))
	fmt.Printf("%q\n", Normalize("   "))
}

