import "fmt"

type Parser struct{ sep string } // ot

func NewParser(sep string) *Parser { return &Parser{sep: sep} }

func (p *Parser) Parse(s string) []string { // fe'l
	var out []string
	cur := ""
	for _, r := range s {
		if string(r) == p.sep {
			out = append(out, cur)
			cur = ""
			continue
		}
		cur += string(r)
	}
	return append(out, cur)
}

func main() {
	fmt.Println(NewParser(",").Parse("a,b,c"))
}

