import (
	"bufio"
	"bytes"
	"fmt"
	"strings"
)

func main() {
	r := strings.NewReader("salom dunyo") // r — io.Reader
	var buf bytes.Buffer                  // buf — bufer
	w := bufio.NewWriter(&buf)            // w — io.Writer
	sc := bufio.NewScanner(r)             // sc — scanner
	sc.Split(bufio.ScanWords)
	for sc.Scan() {
		fmt.Fprintf(w, "[%s]", sc.Text())
	}
	if err := w.Flush(); err != nil { // err — xato
		fmt.Println(err)
	}
	fmt.Println(buf.String())
}

