func withdraw(balance, amount int) (int, error) {
	if amount <= 0 {
		return balance, errors.New("summa musbat bo'lsin")
	}
	if amount > balance {
		return balance, errors.New("mablag' yetarli emas")
	}
	return balance - amount, nil // asosiy yo'l chapda, ichma-ich if yo'q
}

func main() {
	for _, amt := range []int{500, -5, 5000} {
		b, err := withdraw(1000, amt)
		fmt.Println(b, err)
	}
}

