import "fmt"

func Abs(n int) int {
	if n < 0 {
		return -n
	}
	return n
}

func main() {
	// Testda: if got != want { t.Errorf("Abs(%d) = %d; want %d", in, got, want) }
	for _, tc := range []struct{ in, want int }{{-5, 5}, {3, 3}, {0, 0}} {
		got := Abs(tc.in)
		fmt.Printf("Abs(%d) = %d; want %d — %t\n", tc.in, got, tc.want, got == tc.want)
	}
}
